#!/usr/bin/env python3
"""Import selected Lucide SVGs from a local upstream archive and generate Scoop assets."""

import argparse
import json
import tarfile
import xml.etree.ElementTree as ET
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent / "sysroot/src/scoop.icons.lucide"
VERSION = "1.70.0"


def identifier(name):
    first, *rest = name.split("-")
    return first + "".join(part.capitalize() for part in rest)


def declaration(name):
    return (
        "// Generated by scripts/update_lucide.py; see ../../LICENSE.\n"
        "package scoop.icons.lucide\n\n"
        "import scoop.compiler.includeStr\n"
        "import scoop.graphics.svg.SvgAsset\n\n"
        f"public val {identifier(name)}: SvgAsset get() {{\n"
        f'    return SvgAsset(includeStr("../../assets/{name}.svg"))\n'
        "}\n"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--archive", type=Path, help=f"Local lucide-static-{VERSION}.tgz")
    parser.add_argument("--check", action="store_true", help="Check generated declarations")
    args = parser.parse_args()
    if args.archive and args.check:
        parser.error("--archive and --check are mutually exclusive")
    names = ROOT.joinpath("icons.txt").read_text().splitlines()
    if len(names) != len(set(names)) or any(not identifier(name).isidentifier() for name in names):
        raise ValueError("icons.txt requires unique icon names")
    assets = ROOT / "assets"
    generated = ROOT / "src/generated"
    if args.archive:
        with tarfile.open(args.archive) as archive:
            package = json.load(archive.extractfile("package/package.json"))
            if package["name"] != "lucide-static" or package["version"] != VERSION:
                raise ValueError(f"expected lucide-static {VERSION}")
            assets.mkdir(parents=True, exist_ok=True)
            for name in names:
                data = archive.extractfile(f"package/icons/{name}.svg").read()
                assets.joinpath(name + ".svg").write_bytes(data)
            ROOT.joinpath("LICENSE").write_bytes(archive.extractfile("package/LICENSE").read())
    generated.mkdir(parents=True, exist_ok=True)
    for name in names:
        root = ET.fromstring(assets.joinpath(name + ".svg").read_bytes())
        if any(
            root.get(key) != value
            for key, value in (("width", "24"), ("height", "24"), ("viewBox", "0 0 24 24"))
        ):
            raise ValueError(f"{name}: expected the Lucide 24-unit grid")
        for node in root.iter():
            if node.tag.split("}")[-1] not in {
                "svg",
                "path",
                "circle",
                "ellipse",
                "rect",
                "line",
                "polyline",
                "polygon",
            }:
                raise ValueError(f"{name}: SVG element is outside the icon baseline: {node.tag}")
        path = generated / (name + ".scoop")
        source = declaration(name)
        if args.check:
            if not path.exists() or path.read_text() != source:
                raise ValueError(f"regenerate {path}")
        else:
            path.write_text(source)
    expected = {name + ".scoop" for name in names}
    for path in generated.glob("*.scoop"):
        if path.name not in expected:
            if args.check:
                raise ValueError(f"obsolete generated entry: {path}")
            path.unlink()
    print(f"{'Checked' if args.check else 'Generated'} {len(names)} Lucide {VERSION} assets")


if __name__ == "__main__":
    main()
